INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('acf7eaf1-807b-5f1d-ab6b-ef2ac55a1fa9'::uuid, '98780651-4cd6-5cb5-9f94-91fc25025610'::uuid, 'Quels types de projets réalisez-vous ?', 'Nous travaillons sur une grande variété de projets : résidences, villas, bureaux, entreprises, et espaces commerciaux. Chaque projet est conçu sur-mesure pour répondre aux besoins spécifiques de nos clients.', '["https://assets.cdn.filesafe.space/BvQFf9kgW0dH6k84jTY2/media/977aa898-f8c8-40f6-972b-5da278282948.png", "https://assets.cdn.filesafe.space/Fl2YNiTujpODNIFrvGsv/media/67851a388fcd5060886b484e.png"]'::jsonb, 'https://assets.cdn.filesafe.space/BvQFf9kgW0dH6k84jTY2/media/977aa898-f8c8-40f6-972b-5da278282948.png', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '8.5.4' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('fe72ac86-8abe-52fc-8653-10e446840f55'::uuid, '98780651-4cd6-5cb5-9f94-91fc25025610'::uuid, 'Quels sont les délais de réalisation ?', 'Les délais varient en fonction de la taille et de la complexité du projet. Nous nous engageons à respecter les délais convenus tout en garantissant un travail de qualité.', '["https://assets.cdn.filesafe.space/Fl2YNiTujpODNIFrvGsv/media/678519d68898a9961b2566da.png"]'::jsonb, 'https://assets.cdn.filesafe.space/Fl2YNiTujpODNIFrvGsv/media/678519d68898a9961b2566da.png', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '8.5.4' LIMIT 1));
