INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('b494f6c5-0afa-590a-9ca5-a01ae85098b8'::uuid, '6cc198fa-7a7b-5cb5-af23-3e47dd676945'::uuid, 'Intervenez-vous pour les copropriétés et immeubles à Tanger ?', 'Oui. Nous travaillons régulièrement avec des syndics de copropriété, des gérants d immeubles et des promoteurs immobiliers à Tanger. Nous proposons une coordination adaptée aux contraintes des parties communes et aux délais de décision en assemblée générale.', '["https://etanche.ma/wp-content/uploads/2026/03/Etancheite-Toiture-Terrasse-1024x559.webp", "https://etanche.ma/wp-content/uploads/2026/03/Etancheite-Toiture-Terrasse.webp"]'::jsonb, 'https://etanche.ma/wp-content/uploads/2026/03/Etancheite-Toiture-Terrasse-1024x559.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.2.6' LIMIT 1));
