INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('2bf90dc7-7121-5cf0-a72d-b5e931e76b26'::uuid, '2f2b1c7a-9c6c-58d8-a409-966a2be99d6c'::uuid, 'Pourquoi choisir GMCR pour vos projets privés et publiques au Maroc ?', 'Expertise Polyvalente : GMCR offre une expertise polyvalente en matière de construction, bâtiment, voirie et réseaux divers, ce qui permet aux entreprises privées ou aux établissements publiques de consolider plusieurs aspects de leurs projets sous une seule entité compétente.', '["https://gmcr.ma/assets/images/-chantier-construction-usine-1000x526.webp", "https://gmcr.ma/assets/images/mot-du-directeur-gmcr-460x242.webp"]'::jsonb, 'https://gmcr.ma/assets/images/-chantier-construction-usine-1000x526.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('b23110a4-24ce-5365-ade9-7233ef7f335c'::uuid, '2f2b1c7a-9c6c-58d8-a409-966a2be99d6c'::uuid, 'Gestion de Projet Avancée :', 'Avec une gestion de projet avancée, GMCR assure une coordination efficace, une communication transparente et une livraison en temps voulu, des éléments essentiels pour les entreprises internationales qui ont des échéances strictes. <a role="button" class="panel-title', '["https://gmcr.ma/assets/images/gmcr-tanger-1162x612.webp"]'::jsonb, 'https://gmcr.ma/assets/images/gmcr-tanger-1162x612.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
